"""One-time V1 -> V2 migration, preserving the existing game's renderer and controls."""
import re
from pathlib import Path
p=Path('game.js')
s=p.read_text(encoding='utf-8')
def fn(name,code):
 global s
 pattern=r'^function '+re.escape(name)+r'\(.*?(?=^(?:function |const |let |document\.|render\(\);)|\Z)'
 s,n=re.subn(pattern,lambda _:code.strip()+'\n',s,count=1,flags=re.S|re.M)
 assert n,name

s=s.replace("const STORE='midnight-museum-v1'", "const STORE='midnightMuseum:v2:save'")
a=s.index('const fresh=');b=s.index('const escapeHTML=',a)
s=s[:a]+'''const Session=window.MuseumSession;
const fresh=Session.freshSession;
let state=Session.loadSession()||fresh();
if(state.started){state.resumeRoute??={screen:state.screen,station:state.station,task:state.task,index:state.index};state.screen='intro';state.paused=true;}
let teacher=false, selected=state.selection, owner=state.selectedOwner, feedback='', good=false, hint=false, subtitle=false, memoryPhase=state.memory?.phase||'study', memoryDeadline=state.memory?.deadline||0, memoryTimer, dragged=null;
const roomBG=['security_hall_clean','dinosaur_gallery_3d','living_paintings_gallery_3d','egyptian_chamber_3d','lost_found_office_3d','clock_tower_3d'];
''' +s[b:]
s=s.replace("const save=()=>{try{localStorage.setItem(STORE,JSON.stringify({...state,version:1}));}catch(e){}};",'''const save=()=>{
 if(!state.started)return;
 if(state.screen!=='intro')state.resumeRoute={screen:state.screen,station:state.station,task:state.task,index:state.index};
 state.selection=selected;state.selectedOwner=owner;
 state.updatedAt=new Date().toISOString();
 state.route={screen:state.resumeRoute?.screen||state.screen,stationId:station().id,taskId:task().id,questionIndex:state.index};
 state.completedQuestionIds=Object.keys(state.correct);state.skippedQuestionIds=Object.keys(state.skipped);state.unlockedClueIds=state.clues.map(n=>'CLUE_'+(n+1));
 state.correctAnswersByQuestion=Object.fromEntries(DATA.stations.flatMap(s=>s.tasks.flatMap(t=>t.questions.filter(q=>state.correct[q.id]).map(q=>[q.id,String(answer(q))]))));
 state.elapsedLessonSeconds=state.elapsed;
 try{localStorage.setItem(STORE,JSON.stringify(state));}catch{feedback='Progress could not be saved. Check browser storage.';}
};''')
s=s.replace('const answer=q=>q.correct??q.correctItem;', 'const answer=q=>q.correctId;')
fn('path',"""function path(key){if(!A[key])throw new Error('Missing V2 asset '+key);return A[key];}""")
fn('assetFor',"""function assetFor(value){return DATA.stations.flatMap(s=>s.tasks.flatMap(t=>t.questions)).find(q=>answer(q)===value&&q.assetId)?.assetId||Object.keys(A).find(k=>k.split('/').at(-1)===value);}""")
fn('header',r'''function header(){return `<header><div class="brand">☾ Midnight Museum <span class="version">V2</span></div><div class="controls">${btn('Home','home','small')}${state.started?btn('Save & Exit','exit','small'):''}<span class="timer" id="timer">${fmt(state.elapsed)} / 50:00</span>${btn(state.paused?'Resume':'Pause','pause','small')}<select id="mode" aria-label="Question mode"><option value="Quick" ${state.mode==='Quick'?'selected':''}>CLASSROOM / QUICK</option><option value="Full" ${state.mode==='Full'?'selected':''}>FULL</option></select>${btn('Evidence '+state.clues.length+'/6','notebook','small')}${btn('Map','map','small')}${btn(state.mute?'Sound off':'Sound on','mute','small')}${btn('Full screen','fullscreen','small')}${btn('Settings','settings','small')}${state.elapsed>=3000?btn('Wrap Up','wrap-up','small primary'):''}</div></header>`;}''')
fn('enter',r'''function enter(screen){state.screen=screen;if(screen==='task')prepareMemory();save();render();}''')
fn('resetTransient',r'''function resetTransient(){selected=null;owner=null;feedback='';good=false;hint=false;subtitle=false;clearTimeout(memoryTimer);if(state.screen==='task')prepareMemory();}''')
fn('render',r'''function render(){clearTimeout(memoryTimer);app.innerHTML=header()+screenHTML();bind();window.drawScenes();updateTimer();if(state.screen==='task'&&task().mechanic==='memory'){prepareMemory();if(memoryPhase==='study')memoryTimer=setTimeout(()=>{memoryPhase='recall';state.memory.phase='recall';render();},Math.max(0,memoryDeadline-Date.now()));}save();}''')
fn('intro',r'''function intro(){let legacy=false;try{legacy=!!localStorage.getItem('midnight-museum-v1');}catch{}return `<main class="hero" style="--scene:url('${path('backgrounds/museum_intro_3d')}')"><div class="hero-copy"><div class="eyebrow">An English adventure · A1 · Grades 3–5</div><h1>The Midnight<br>Museum Mysteries</h1><p>The clock has stopped.<br>The Moon Key is missing.<br>Six rooms. One curious mystery.</p><div class="tags"><span>50-minute adventure</span><span>17 activities</span><span>170 rounds</span></div><div class="row">${state.started?btn('CONTINUE','continue','primary')+btn('START AGAIN','new-lesson'):btn('START','start','primary')}${btn('HOW TO PLAY','how-to','small')}</div>${legacy&&!state.started?'<p class="subtle">A V1 lesson is saved. Start a new V2 game; your V1 save will stay safe.</p>':''}</div>${image('characters/professor_hoot_3d','mascot','Professor Hoot, your owl detective')}</main>`;}''')
s=s.replace("const OPENING='Welcome, detectives! It is midnight. Oh no! The Moon Key is missing, and our big clock has stopped! Can you help me? We have six rooms to explore. Look, listen, think and speak English. Let’s go!';", "const OPENING='Welcome, detectives! The Moon Key is missing and our museum clock has stopped. Can you help me? We have six rooms to explore!';")
fn('mapScreen',r'''function mapScreen(){return `<main class="page"><div class="eyebrow">The investigation · ${state.clues.length} of 6 clues collected</div><h2>Where will the clues lead us?</h2><p class="subtle">Explore each room. Solve its challenges. Collect a clue.</p><div class="room-grid">${DATA.stations.map((s,i)=>`<button class="room ${i>state.clues.length?'locked':''}" data-room="${i}" ${i>state.clues.length?'disabled':''}>${image('backgrounds/'+roomBG[i],'',s.name)}<div><span>ROOM ${i+1} · ${s.time} ${state.clues.includes(i)?'· CLUE COLLECTED':''}</span><h3>${escapeHTML(s.name)}</h3></div></button>`).join('')}</div>${state.clues.length===6?btn('Go to the finale','finale','primary'):''}</main>`;}''')
fn('roomIntro',r'''function roomIntro(){return `<main class="hero" style="--scene:url('${path('backgrounds/'+roomBG[state.station])}')"><div class="hero-copy"><div class="eyebrow">Station ${state.station+1} / 6 · ${station().time}</div><h1>${escapeHTML(station().name)}</h1><p>Welcome, detectives! We have ${station().tasks.length===2?'two':'three'} challenges. Are you ready?</p>${station().tasks.map((t,i)=>`<p class="challenge-list">${i+1}. ${escapeHTML(t.title)}</p>`).join('')}${btn('Let’s investigate','begin-room','primary')}</div></main>`;}''')
fn('taskScreen',r'''function taskScreen(){state.visited[task().id]=true;state.questionOrders[task().id]??=task().questions.map(q=>q.id);const t=task(),q=question();let prompt=q.prompt;if(t.mechanic==='symbol_choice')prompt=q.prompt.replace(/\[[A-Z]+\]/,'◆');if(t.mechanic==='profession_match')prompt='Who can '+q.prompt+'?';return `<main class="page task-page"><div class="task-head"><div><div class="eyebrow">${escapeHTML(station().name)} · STATION ${state.station+1}/6 · TASK ${state.task+1}/${station().tasks.length} · Q ${state.index+1}/10</div><h2>${escapeHTML(t.title)}</h2></div><div class="rounds" aria-label="Question progress">${t.questions.map((x,i)=>`<span class="dot ${state.correct[x.id]?'done':state.skipped[x.id]?'skipped':''} ${state.index===i?'current':''}"></span>`).join('')}</div></div><p class="prompt">${escapeHTML(prompt)}</p>${teacher?`<div class="teacher">TEACHER · Answer: ${escapeHTML(String(answer(q)))} ${q.correctOwner?' · '+escapeHTML(q.correctOwner):''} ${btn('MARK CORRECT','mark-correct','small')}</div>`:''}${activity()}<div class="feedback ${good?'good':''}" role="status" aria-live="polite">${escapeHTML(feedback)}</div>${hint?`<p class="hint">${escapeHTML(hintText())}</p>`:''}<div class="footer"><div class="row">${btn('Back','back','small')}${btn('Repeat','replay','small')}${btn('Hint','hint','small')}${btn('Skip','skip','small')}</div><div class="row"><span class="subtle">${points()} XP</span>${btn('NEXT','next','primary',!state.correct[q.id]?'disabled':'')}</div></div><div class="subtle" id="pace"></div></main>`;}''')
fn('itemImage',r'''function itemImage(value,kind='',cls=''){const key=assetFor(value);return key?image(key,cls,label(value)):'';}''')
fn('cards',r'''function cards(values,kind='',captions=false,extra=''){return `<div class="cards ${extra}">${values.map(v=>choice(v,itemImage(v)+(captions?`<span class="caption">${label(v)}</span>`:''),'card')).join('')}</div>`;}''')
fn('evidence',r'''function evidence(includeNote=true){return `<div class="evidence-grid">${[0,1,2,3,...(includeNote?[4]:[])].map(i=>`<div class="evidence-card">${image(DATA.stations[i].clueAsset)}<p>${escapeHTML(DATA.stations[i].clue)}${[' · on the floor',' · on the floor',' · in the photo',' · on the stairs',''][i]}</p></div>`).join('')}</div>`;}''')
fn('suspectArt',r'''function suspectArt(v){return image('characters/suspect_'+v+'_3d','',label(v));}''')
fn('suspects',r'''function suspects(clickable=false){return `<div class="cards five">${ordered('suspects',['owl','cat','bat','fox','grey_mouse']).map(v=>clickable?choice(v,suspectArt(v)+`<span>${label(v)}</span>`,'card'):`<div class="card">${suspectArt(v)}<span>${label(v)}</span></div>`).join('')}</div>`;}''')
fn('activity',r'''function activity(){const t=task(),q=question(),values=ordered(t.id+'/tiles',q.options);switch(t.mechanic){
case'true_false':return `<div class="board ${t.id==='S1_T1'?'security-board':'dark'}">${t.id==='S1_T1'?window.securityScene():t.id==='S6_T3'?suspects():evidence()+`<p class="evidence-context">The Moon Key is gold. The window is intact. The clock has stopped.</p>`}</div><div class="answer-row">${choice(true,'TRUE')}${choice(false,'FALSE')}</div>`;
case'find_object':return `<div class="board flash" style="background-image:url('${path('backgrounds/security_hall_clean')}')"><div class="cards">${values.map(v=>{const found=t.questions.some(x=>answer(x)===v&&state.correct[x.id]);return `<button class="card ${found?'found':''}" data-answer="${escapeHTML(JSON.stringify(v))}" ${found?'disabled':''} aria-label="${label(v)}">${itemImage(v)}</button>`;}).join('')}</div></div><div class="inventory">Found: ${t.questions.filter(x=>state.correct[x.id]).length}/10 · Move the torch or use Tab.</div>`;
case'portrait_match':case'picture_choice_10':return `<div class="board">${cards(values)}</div>`;
case'choice_3':return `<div class="board">${cards(ordered(t.id+'/'+q.id,q.options),'',true,'three')}</div>`;
case'drag_drop':return placement('painting');
case'profession_match':return professions();
case'spot_difference':return difference();
case'symbol_choice':{const ids=symbolOptions(answer(q));const reveal=state.symbolOpen===q.id;return `<div class="board center symbol-board">${btn(image(q.assetId,'clue-art','Mystery symbol'),'symbol-open','symbol-button','aria-label="Show word choices"')}</div>${reveal?`<div class="answer-row">${ordered(t.id+'/'+q.id,ids).map(v=>choice(v,label(v))).join('')}</div>`:`<p class="subtle center">Click the symbol to see the words.</p>`}${state.correct[q.id]?`<p class="full-sentence">${escapeHTML(q.prompt.replace(/\[[A-Z]+\]/,answer(q)))}</p>`:''}`;}
case'clothing_choice':return `<div class="board wardrobe"><div class="wardrobe-mummy">${image('characters/mummy_friendly_3d','','A friendly mummy')}</div>${cards(values,'',false,'clothes-grid')}</div>`;
case'memory':return memory();
case'owner_match':return owners();
case'clock_placement':return clockPlacement();
case'multiple_choice':return `<div class="board dark grammar-board">${clockAssembly()}${q.index===3?'<div class="grammar-context"><span class="context-table"></span><span class="context-cat">'+image('egypt/hieroglyphs/cat','','A cat under the table')+'</span></div>':q.index===8?'<div class="grammar-context mouse-context">'+image('characters/suspect_grey_mouse_3d','','A mouse behind the clock')+image('clock/clock_face_3d','','The clock in front of the mouse')+'</div>':''}</div><div class="answer-row">${ordered(q.id+'/words',q.choices).map(v=>choice(v,escapeHTML(v))).join('')}</div>`;
default:throw new Error('Unknown V2 mechanic '+t.mechanic);}}''')
# Remove only mechanics explicitly retired by V2; original files are archived.
for name in ['dress','maze','move']:
 fn(name,'')
s=re.sub(r'^const (boneCoords|paintingCoords|clothingPositions|routeActions|landmarks)=.*\n','',s,flags=re.M)
fn('token',r'''function token(value,kind){return `<button class="card ${selected===value?'selected':''}" draggable="true" data-token="${escapeHTML(JSON.stringify(value))}" aria-label="${escapeHTML(kind==='number'?'Number '+value:label(value))}">${kind==='number'?image('clock/clock_digit_'+String(value).padStart(2,'0'),'',String(value)):itemImage(value)}</button>`;}''')
fn('slotHTML',r'''function slotHTML(value,x,y,filled,kind){return `<button class="slot ${filled?'filled':''}" style="left:${x}%;top:${y}%" data-slot="${escapeHTML(JSON.stringify(value))}" aria-label="${escapeHTML(label(value))} position">${filled?(kind==='number'?image('clock/clock_digit_'+String(value).padStart(2,'0'),'',String(value)):itemImage(value)):kind==='number'?'·':'+'}</button>`;}''')
fn('placement',r'''function placement(){const qs=task().questions,castle=state.index>=5;const coords=[[58,31],[28,38],[31,86],[82,74],[40,67],[30,29],[47,38],[68,23],[25,34],[81,56]];const subset=qs.filter(q=>(q.index>5)===castle);const tokens=ordered(task().id+'/'+(castle?'castle':'village'),subset.map(answer));return `<div class="board workspace painting-workspace"><div class="canvas painting"><div class="painting-stage" style="background-image:url('${path('paintings/'+(castle?'castle':'village')+'_empty_3d')}')">${subset.map(q=>{const [x,y]=coords[q.index-1];return slotHTML(answer(q),x,y,!!state.correct[q.id],'painting');}).join('')}</div></div><div class="cards">${tokens.filter(v=>!state.correct[qs.find(q=>answer(q)===v).id]).map(v=>token(v,'painting')).join('')}</div></div><p class="subtle">Drag a picture to its place, or click a picture and then a target.</p>`;}''')
fn('difference',r'''function difference(){const pair=question().pairId;return `<div class="board difference-board"><div class="pair">${['A','B'].map(side=>`<div class="picture" data-picture="${pair}">${image(HOT[pair].a.replace(/\.png$/,''),'','Picture '+side)}${side==='B'?HOT[pair].changes.map(h=>image(h.asset.replace(/\.png$/,''),'difference-layer','')).join(''):''}<b>${side}</b>${HOT[pair].changes.map((h,i)=>{const q=task().questions.find(q=>answer(q)===h.id);const [x,y,w,ht]=h.rect;return `<button class="hotspot ${state.correct[q.id]?'marked':''}" data-answer="${escapeHTML(JSON.stringify(h.id))}" style="left:${x*100}%;top:${y*100}%;width:${w*100}%;height:${ht*100}%" aria-label="Explore picture ${side}, area ${i+1}"></button>`;}).join('')}</div>`).join('')}</div></div><p class="subtle">Find the change in either picture. Describe it aloud.</p>`;}''')
fn('memory',r'''function memory(){prepareMemory();const vals=ordered(task().id+'/memory',task().questions.map(answer));const recall=memoryPhase!=='study';const opts=ordered(question().id+'/memory-options',[answer(question()),...vals.filter(v=>v!==answer(question())).slice(0,3)]);return `<div class="board memory-board"><div class="cards">${vals.map(v=>`<div class="card ${recall&&v===answer(question())?'memory-empty':''}" data-memory-id="${v}">${itemImage(v)}</div>`).join('')}</div></div><div class="center memory-controls">${!recall?`<p class="hint">Remember all ten objects. <span id="memory-count"></span></p>${btn('Ready — hide one object','memory-hide','small')}`:`<div class="answer-row memory-options">${opts.map(v=>choice(v,itemImage(v),'card')).join('')}</div>${btn('Reveal missing object','memory-reveal','small')}${memoryPhase==='reveal'?`<p class="prompt">The ${label(answer(question()).replace('memory_','')).toLowerCase()} is missing.</p>${teacher?btn('MARK CORRECT','mark-correct','primary'):''}`:''}`}</div>`;}''')
fn('owners',r'''function owners(){const start=state.index<5?0:5;const qs=task().questions.slice(start,start+5);const people=ordered(task().id+'/owners/'+start,qs.map(q=>q.correctOwner)),items=ordered(task().id+'/items/'+start,qs.map(answer));return `<div class="board owner-board"><div class="owners owner-portraits">${people.map(o=>{const q=qs.find(q=>q.correctOwner===o);return `<button data-owner="${o}" class="card ${owner===o?'selected':''}">${image('owners/'+o,'',label(o.replace('owner_','')))}<span class="caption">${label(o.replace('owner_',''))}${state.correct[q.id]?' ✓':''}</span></button>`;}).join('')}</div><div class="cards owner-items">${items.map(v=>`<button class="card" data-possession="${v}" draggable="true">${itemImage(v)}</button>`).join('')}</div></div><p class="subtle">Choose a person and their object, or drag the object to its owner.</p>`;}''')
fn('clockMarkup',r'''function clockMarkup(filledAll=false){return `<div class="clock ${filledAll?'running':''}">${image('clock/clock_face_3d','clock-face','A twelve-hour clock')}${Array.from({length:12},(_,i)=>i+1).map(n=>{const angle=n*Math.PI/6;const q=DATA.stations[5].tasks[0].questions.find(q=>answer(q)===n);return slotHTML(n,50+Math.sin(angle)*38,50-Math.cos(angle)*38,filledAll||n===10||n===11||state.correct[q?.id]||state.autoFilled.includes(q?.id),'number');}).join('')}<div class="hand"></div><div class="hand short"></div></div>`;}''')
fn('clockPlacement',r'''function clockPlacement(){return `<div class="board workspace clock-workspace">${clockMarkup()}<div class="cards">${ordered(task().id+'/numbers',task().questions.map(answer)).filter(v=>!state.correct[task().questions.find(q=>answer(q)===v).id]&&!state.autoFilled.includes(task().questions.find(q=>answer(q)===v).id)).map(v=>token(v,'number')).join('')}</div></div><p class="subtle">Select a number, then its clock position. You can also drag it.</p>`;}''')
fn('eligible',r'''function eligible(){return station().tasks.every(t=>state.visited[t.id]&&(state.mode==='Full'?t.questions:t.coreQuestionIds.map(n=>t.questions[n-1])).every(q=>state.correct[q.id]||state.skipped[q.id]));}''')
fn('completeScreen',r'''function completeScreen(){const t=task(),remaining=t.questions.filter(q=>!state.correct[q.id]&&!state.skipped[q.id]);return `<main class="page center"><div class="eyebrow">Station ${state.station+1} · Task ${state.task+1} complete</div><h1>Wonderful detective work!</h1><p class="prompt">${countAttempts(t)} of 10 questions explored</p><p class="subtle">${points()} XP · No penalties for trying again</p>${state.mode==='Quick'&&remaining.length?btn('More questions','more','small'):''}${t.id==='S6_T2'&&state.clockAssemblyStage<10?btn('Finish clock','finish-clock','primary'):''}${t.id==='S6_T2'?clockAssembly():''}<div class="answer-row">${btn('Review this task','review')}${state.task<station().tasks.length-1?btn('Next challenge','next-task','primary'):btn('Finish station','finish-station','primary',!eligible()?'disabled':'')}</div><p class="subtle">${station().tasks.map(t=>`${escapeHTML(t.title)}: ${countAttempts(t)}/10`).join(' · ')}</p></main>`;}''')
fn('clueScreen',r'''function clueScreen(){return `<main class="page center"><div class="eyebrow">Evidence discovered · Clue ${state.station+1}/6</div><h1>${escapeHTML(station().clue)}</h1>${image(station().clueAsset,'clue-art',station().clue)}<p class="prompt">Fantastic detective work! We found a clue.<br>Let’s put it in our notebook.</p>${btn('COLLECT CLUE','collect','primary')}</main>`;}''')
s=s.replace("const recapQuestions=['Who took the Moon Key?','Why did he take it?','Where was the grey fur?','What was the mummy wearing?','Which room did you like best?'];", "const recapQuestions=['Who took the Moon Key?','Why did he take it?','Where did you find the grey fur?','What clothes did you see?','Which room did you like best?'];")
s=s.replace("image('characters.pip_mouse'", "image('characters/pip_mouse_v2'")
fn('hintText',r'''function hintText(){return state.correct[question().id]?'Well done! Say it in a complete sentence.':task().mechanic==='spot_difference'?'Compare the same place in pictures A and B.':task().mechanic==='memory'?'Think about the empty space. Which object was there?':'Look carefully. Read the sentence. Which picture is correct?';}''')
fn('submit',r'''function submit(value){if(state.screen!=='task')return;const q=question();state.attempted[q.id]=true;const ok=value===answer(q);if(ok){if(!state.correct[q.id])chime();state.correct[q.id]=true;delete state.skipped[q.id];if(task().mechanic==='multiple_choice'){state.clockAssemblyStage=Math.max(state.clockAssemblyStage,task().questions.filter(q=>state.correct[q.id]).length);state.lastClockAnimation=Date.now();}good=true;feedback=q.feedbackText;if(task().mechanic==='drag_drop'||task().mechanic==='clock_placement'){state.placedItems[task().id]??=[];if(!state.placedItems[task().id].includes(q.id))state.placedItems[task().id].push(q.id);}}else{good=false;feedback='Good try — have another look!';}render();}''')
fn('nextQuestion',r'''function nextQuestion(skip=false){if(!skip&&!state.correct[question().id])return;if(skip){state.attempted[question().id]=true;if(!state.correct[question().id])state.skipped[question().id]=true;}const seq=questionSequence(),pos=seq.indexOf(state.index);if(pos===seq.length-1||pos<0){if(task().id==='S6_T1'&&state.mode==='Quick')state.autoFilled=[...new Set([...state.autoFilled,...task().questions.filter(q=>!state.correct[q.id]).map(q=>q.id)])];enter('task_complete');return;}state.index=seq[pos+1];resetTransient();render();}''')
fn('finishStation',r'''function finishStation(){if(!eligible())return;if(state.station===5&&!state.suspect){showModal(`<h2>Who took the Moon Key?</h2><p>Check the fur, ears, tail and wings. Make your final choice.</p>${suspects(true)}<p id="suspect-feedback" role="status"></p>`);modal.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const v=JSON.parse(b.dataset.answer);if(v==='grey_mouse'){state.suspect=true;modal.close();enter('station_clue');}else modal.querySelector('#suspect-feedback').textContent='Good try. Check the clues again.';});}else enter('station_clue');}''')
fn('showModal',r'''function showModal(html){modal.innerHTML=html+`<div class="row dialog-footer">${btn('Close','close','small')}</div>`;if(!modal.open)modal.showModal();modal.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}''')
fn('notebook',r'''function notebook(){state.evidenceNotebookOpen=true;save();showModal(`<div class="eyebrow">Evidence notebook · ${state.clues.length}/6</div><h2>Our clues</h2><div class="evidence-grid">${state.clues.map(i=>`<div class="evidence-card">${image(DATA.stations[i].clueAsset,'',DATA.stations[i].clue)}<p>${i+1}. ${escapeHTML(DATA.stations[i].clue)}</p></div>`).join('')||'<p>Explore the rooms to find your first clue.</p>'}</div>`);}''')
fn('settings',r'''function settings(){showModal(`<h2>Teacher controls</h2><p>Quick: five or six core rounds per challenge, with optional bonus questions. Full: all ten rounds. The timer never interrupts a question.</p><p>Enter: select / next · Space: repeat · Arrows: move focus · Esc: close · Ctrl+Shift+T: teacher answers.</p><p>Your lesson stays in this browser on this device. Save & Exit returns to the menu.</p>${btn('Restart task','restart-task','small')}${btn('START AGAIN','new-lesson','small')}`);}''')
fn('action',r'''function action(name){switch(name){
case'close':state.evidenceNotebookOpen=false;modal.close();break;
case'home':case'exit':if(state.screen!=='intro')save();state.paused=true;enter('intro');break;
case'continue':if(state.resumeRoute){Object.assign(state,state.resumeRoute);state.paused=false;selected=state.selection;owner=state.selectedOwner;render();if(state.evidenceNotebookOpen)notebook();}break;
case'new-lesson':showModal(`<h2>Start a new lesson? Your saved progress will be replaced.</h2><div class="answer-row">${btn('CANCEL','close')}${btn('YES, START AGAIN','confirm-new','primary')}</div>`);break;
case'confirm-new':modal.close();state=fresh();teacher=false;selected=null;owner=null;startLesson();break;
case'start':if(state.started)action('new-lesson');else startLesson();break;
case'how-to':showModal(`<h2>How to play</h2><p>Read, look and speak English. Choose a picture, match an object, or solve a puzzle. Collect six clues and help Professor Hoot find the Moon Key.</p><p>The teacher controls one screen. Quick fits a 50-minute lesson; Full includes all 170 rounds. Continue works in the same browser on this device.</p>`);break;
case'accept-opening':modal.close();enter('museum_map');break;
case'pause':state.paused=!state.paused;render();break;
case'mute':state.mute=!state.mute;window.speechSynthesis?.cancel();render();break;
case'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>{});break;
case'notebook':notebook();break;case'settings':settings();break;
case'map':if(state.started)enter('museum_map');break;
case'begin-room':state.task=0;state.index=questionSequence()[0];resetTransient();enter('task');break;
case'next':nextQuestion();break;case'skip':nextQuestion(true);break;
case'hint':hint=!hint;render();break;
case'replay':subtitle=true;if(state.screen==='task'){speak(question().prompt);if(task().mechanic==='multiple_choice')state.lastClockAnimation=Date.now();}render();break;
case'back':{const seq=questionSequence(),pos=seq.indexOf(state.index);if(pos>0)state.index=seq[pos-1];else if(state.task>0){state.task--;state.index=questionSequence()[0];}else{enter('station_intro');break;}resetTransient();enter('task');break;}
case'more':state.bonus[task().id]=true;state.index=task().questions.findIndex(q=>!state.correct[q.id]&&!state.skipped[q.id]);if(state.index<0)state.index=0;resetTransient();enter('task');break;
case'review':state.index=questionSequence()[0];resetTransient();enter('task');break;
case'next-task':state.task++;state.index=questionSequence()[0];resetTransient();enter('task');break;
case'finish-station':finishStation();break;
case'collect':if(!state.clues.includes(state.station))state.clues.push(state.station);state.clues.sort((a,b)=>a-b);enter(state.station===5?'reveal':'museum_map');break;
case'finale':if(state.suspect)enter('reveal');break;
case'wrap-up':showModal(`<h2>Finish the investigation together</h2><p>Our clues point to a small grey animal. Who borrowed the key to help repair the clock?</p>${suspects(true)}<p id="wrap-feedback"></p>`);modal.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(JSON.parse(b.dataset.answer)==='grey_mouse'){state.suspect=true;state.wrappedUp=true;modal.close();enter('reveal');}else modal.querySelector('#wrap-feedback').textContent='Look at the ears and tail. Try again.';});break;
case'insert-key':state.keyInserted=true;render();break;
case'wrong-final':feedback='Try the place Pip wanted to repair.';render();break;
case'start-clock':state.clockStarted=true;chime();render();break;
case'recap':if(state.recap<4){state.recap++;render();}else{state.completed=true;enter('victory');}break;
case'print':window.print();break;
case'memory-hide':memoryPhase='recall';state.memory.phase='recall';render();break;
case'memory-reveal':memoryPhase='reveal';state.memory.phase='reveal';render();break;
case'mark-correct':if(teacher)submit(answer(question()));break;
case'symbol-open':state.symbolOpen=question().id;render();break;
case'finish-clock':state.clockAutoFinished=true;state.clockAssemblyStage=10;state.autoFilled=[...new Set([...state.autoFilled,...task().questions.filter(q=>!state.correct[q.id]).map(q=>q.id)])];state.lastClockAnimation=Date.now();render();break;
case'restart-task':modal.close();state.index=questionSequence()[0];if(task().mechanic==='memory')state.memory=null;resetTransient();enter('task');break;
}save();}''')
fn('bind',r'''function bind(){app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));app.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{state.station=Number(b.dataset.room);state.task=0;state.index=0;enter('station_intro');});app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>submit(JSON.parse(b.dataset.answer)));app.querySelector('#mode').onchange=e=>{state.mode=e.target.value;render();};app.querySelectorAll('[data-token]').forEach(b=>{b.onclick=()=>{selected=JSON.parse(b.dataset.token);render();};b.ondragstart=e=>{dragged=JSON.parse(b.dataset.token);e.dataTransfer.setData('text/plain',JSON.stringify(dragged));};});app.querySelectorAll('[data-slot]').forEach(b=>{b.onclick=()=>{if(selected!==null)place(selected,JSON.parse(b.dataset.slot));};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();let v;try{v=JSON.parse(e.dataTransfer.getData('text/plain'));}catch{v=dragged;}place(v,JSON.parse(b.dataset.slot));};});const flash=app.querySelector('.flash');if(flash)flash.onpointermove=e=>{const r=flash.getBoundingClientRect();flash.style.setProperty('--x',(e.clientX-r.left)+'px');flash.style.setProperty('--y',(e.clientY-r.top)+'px');};app.querySelectorAll('[data-picture]').forEach(p=>p.onclick=e=>{if(!e.target.closest('[data-answer]')){feedback='Look closely. Try another place.';good=false;render();}});app.querySelectorAll('[data-owner]').forEach(b=>{b.onclick=()=>{owner=b.dataset.owner;render();};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();matchOwner(b.dataset.owner,e.dataTransfer.getData('text/plain'));};});app.querySelectorAll('[data-possession]').forEach(b=>{b.onclick=()=>matchOwner(owner,b.dataset.possession);b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.possession);});app.querySelectorAll('[data-skill]').forEach(b=>{b.onclick=()=>{selected=b.dataset.skill;render();};b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.skill);});app.querySelectorAll('[data-profession]').forEach(b=>{b.onclick=()=>matchSkill(selected,b.dataset.profession);b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();matchSkill(e.dataTransfer.getData('text/plain'),b.dataset.profession);};});}''')
# The standard focus controls remain, without retired maze behavior.
