s=s.replace("save();},1000);", "save();},1000);")
extra=r'''
function ordered(key,values){
 const old=state.tileOrders[key];if(old&&old.length===values.length&&old.every(v=>values.includes(v)))return old;
 let result=Session.shuffled(values,state.sessionId+'/'+key);
 if(task().id==='S2_T1'&&values.length===10){let i=0;while(result.some((v,n)=>v===values[n])&&i<100){result=Session.shuffled(values,state.sessionId+'/'+key+'/'+(++i));}}
 state.tileOrders[key]=result;return result;
}
function questionSequence(){return state.mode==='Full'||state.bonus[task().id]?Array.from({length:10},(_,i)=>i):task().coreQuestionIds.map(n=>n-1);}
function startLesson(){state.started=true;state.paused=false;state.screen='museum_map';save();showModal(`<h2>Professor Hoot</h2><p>${OPENING}</p><p>Children: “We can help!”</p>${btn('We can help!','accept-opening','primary')}`);speak(OPENING);}
function prepareMemory(){if(task().mechanic!=='memory')return;if(state.memory?.questionId!==question().id)state.memory={questionId:question().id,phase:'study',deadline:Date.now()+12000};memoryPhase=state.memory.phase;memoryDeadline=state.memory.deadline;}
function symbolOptions(v){return ({sun:['sun','moon','star'],moon:['moon','sun','star'],star:['star','moon','sun'],cat:['cat','bird','snake'],snake:['snake','cat','bird'],bird:['bird','cat','snake'],boat:['boat','key','crown'],crown:['crown','key','eye'],eye:['eye','star','key'],key:['key','crown','boat']})[v];}
function professions(){const qs=task().questions;return `<div class="board profession-board"><div class="profession-people">${ordered(task().id+'/people',['artist','scientist','teacher','swimmer']).map(v=>`<button class="card" data-profession="${v}">${image('professions/'+v+'_3d','',label(v))}<span>${label(v)}</span><span class="match-count">${qs.filter(q=>answer(q)===v&&state.correct[q.id]).length} matched</span></button>`).join('')}</div><div class="cards skills-grid">${ordered(task().id+'/skills',qs.map(q=>q.skillId)).map(skill=>{const q=qs.find(q=>q.skillId===skill);return `<button class="card ${selected===skill?'selected':''} ${state.correct[q.id]?'matched':''}" data-skill="${skill}" draggable="true" ${state.correct[q.id]?'disabled':''}>${image(q.assetId,'','Action picture')}</button>`;}).join('')}</div></div><p class="subtle">Select the action picture, then the person who can do it. You can also drag it.</p>`;}
function matchSkill(skill,profession){if(skill===question().skillId&&profession===answer(question()))submit(profession);else{feedback=skill?'Good try — check the action and the job.':'Choose the action picture first.';good=false;state.attempted[question().id]=true;render();}}
function clockAssembly(){const stage=state.clockAssemblyStage,animate=state.lastClockAnimation&&Date.now()-state.lastClockAnimation<1500;const layers=[['clock_gold_gear_01',15,35,28],['clock_gold_gear_02',44,25,24],['clock_gold_gear_03',61,49,20],['clock_axle',37,38,25],['clock_spring',43,62,30],['clock_hand_minute',45,15,15],['clock_hand_hour',45,30,18]];return `<div class="clock-assembly stage-${stage} ${stage===10?'running':''} ${animate?'build-animation':''}" data-stage="${stage}">${image('clock/clock_face_3d','assembly-frame','Clock mechanism')} ${layers.slice(0,Math.min(stage,7)).map(([name,x,y,w],i)=>`<img class="assembly-part part-${i}" src="${path('clock/'+name)}" style="left:${x}%;top:${y}%;width:${w}%;z-index:${i+1}" alt="${label(name)}">`).join('')}${stage>=8?'<div class="digit-glow"></div>':''}${stage>=9?'<div class="assembly-dial"></div>':''}${stage===10?image('clock/clock_hand_second','assembly-second','The clock is ticking'):''}<span class="assembly-label">Clock restored: ${stage}/10${state.clockAutoFinished?' · Auto-finished':''}</span></div>`;}
modal.addEventListener('close',()=>{state.evidenceNotebookOpen=false;save();});
window.addEventListener('pagehide',save);
window.MuseumDebug={get state(){return state;},get task(){return task();},get question(){return question();},points,phase,render,validateSession:Session.validateSession};
'''
s=s.replace('render();\n', 'render();\n',1)
pos=s.rfind('render();')
s=s[:pos]+extra+'\n'+s[pos:]
# All live asset paths must resolve through the V2 manifest, never public/V1 aliases.
s=s.replace("${state.clues.length} / 6 clues", "${state.clues.length} / 6 clues")
s=s.replace('6 / 6 clues · ${points()}', '${state.clues.length} / 6 clues · ${points()}')
s=s.replace("${btn('Explore the museum','map')}","${btn('HOME','home')}${btn('START AGAIN','new-lesson')}")
p.write_text(s,encoding='utf-8')
print('Updated existing game.js to V2; original engine retained in archive/v1.')
